pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testRegression_property() public {
        address randomCaller = address(0x1234);
        bytes32 assertionId = keccak256("test");
        bool ok;
        vm.prank(randomCaller);
        try c.assertionDisputedCallback(assertionId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
